// Checkout.test.tsx
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mock contexts with surgical precision
const mockClearCart = vi.fn();
const mockProcessPayment = vi.fn();

vi.mock('./CartContext', () => ({
  useCart: () => ({
    items: [{ id: '1', name: 'Widget', price: 29.99 }],
    total: 29.99,
    clearCart: mockClearCart,
  }),
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment }),
}));

describe('Checkout Component', () => {
  const user = userEvent.setup();

  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-12345' });
  });

  describe('Happy Path - Complete Checkout Flow', () => {
    it('completes full checkout from shipping to confirmation', async () => {
      const onComplete = vi.fn();
      render(<Checkout onComplete={onComplete} />);

      // Shipping step
      await user.type(screen.getByLabelText(/street address/i), '123 Beacon Hill');
      await user.type(screen.getByLabelText(/city/i), 'Boston');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '02108');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'Charles Winchester');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review step
      expect(screen.getByText(/widget/i)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation
      await waitFor(() => {
        expect(screen.getByRole('status')).toHaveTextContent('ORD-12345');
      });
      expect(onComplete).toHaveBeenCalledWith('ORD-12345');
    });
  });

  describe('Form Validation', () => {
    it('displays error for invalid ZIP code format', async () => {
      render(<Checkout />);

      await user.type(screen.getByLabelText(/street/i), '123 Main');
      await user.type(screen.getByLabelText(/city/i), 'Boston');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue/i }));

      expect(await screen.findByRole('alert')).toHaveTextContent(/valid zip/i);
    });

    it('marks invalid card number with aria-invalid', async () => {
      render(<Checkout />);
      // Navigate to payment step first... then:

      await user.type(screen.getByLabelText(/card number/i), '1234');
      await user.click(screen.getByRole('button', { name: /review/i }));

      expect(screen.getByLabelText(/card number/i)).toHaveAttribute('aria-invalid', 'true');
    });
  });

  describe('Error States', () => {
    it('displays payment failure and allows retry', async () => {
      mockProcessPayment.mockRejectedValueOnce(new Error('Insufficient funds'));
      render(<Checkout />);
      // Navigate to review step...

      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(await screen.findByRole('alert')).toHaveTextContent(/insufficient funds/i);
      expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
    });
  });

  describe('Accessibility', () => {
    it('has no accessibility violations', async () => {
      const { container } = render(<Checkout />);
      const results = await axe(container);
      expect(results).toHaveNoViolations();
    });
  });

  describe('Edge Cases', () => {
    it('displays empty cart message when no items', () => {
      vi.mocked(useCart).mockReturnValueOnce({ items: [], total: 0, clearCart: mockClearCart });
      render(<Checkout onCancel={vi.fn()} />);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });
  });
});
